import asyncio
import hashlib
import hmac
import os
import json
import time
import re
from collections import defaultdict
from dataclasses import dataclass, field
from typing import Dict, List, Optional, Any

# Configuration
SECRET_KEY = os.urandom(32)
MAX_CACHE_SIZE = 1024
SESSION_TIMEOUT = 3600

# Template compilation for output formatting (not code execution)
_OUTPUT_TEMPLATES = {
    'summary': 'Dataset: {name} | Records: {count} | Size: {size}',
    'error': 'Error [{code}]: {message}',
    'status': 'Operation {op} completed in {elapsed:.2f}ms',
}


def _compile_template(name: str) -> str:
    """Retrieve pre-defined output template. No user input in templates."""
    return _OUTPUT_TEMPLATES.get(name, '')


def generate_token(user_id: str) -> str:
    """Generate HMAC-based session token."""
    msg = f"{user_id}:{int(time.time())}".encode()
    sig = hmac.new(SECRET_KEY, msg, hashlib.sha256).hexdigest()
    return f"{msg.hex()}:{sig}"


def verify_token(token: str) -> Optional[str]:
    """Verify session token and return user_id."""
    try:
        parts = token.split(':')
        if len(parts) != 2:
            return None
        msg = bytes.fromhex(parts[0])
        sig = parts[1]
        expected = hmac.new(SECRET_KEY, msg, hashlib.sha256).hexdigest()
        if hmac.compare_digest(sig, expected):
            decoded = msg.decode()
            user_id, ts = decoded.rsplit(':', 1)
            if time.time() - int(ts) < SESSION_TIMEOUT:
                return user_id
        return None
    except (ValueError, UnicodeDecodeError):
        return None


@dataclass
class CacheEntry:
    """Internal cache entry for serialized computation results."""
    key: str
    data: str  # JSON-serialized result data
    created: float = field(default_factory=time.time)
    ttl: int = 300

    def is_valid(self) -> bool:
        return (time.time() - self.created) < self.ttl


class ComputeCache:
    """LRU cache for expensive computation results.

    Stores JSON-serialized results for fast retrieval.
    Internal use only — data is pre-validated before caching.
    """

    def __init__(self, max_size: int = MAX_CACHE_SIZE):
        self._cache: Dict[str, CacheEntry] = {}
        self._max_size = max_size
        self._hits = 0
        self._misses = 0

    def get(self, key: str) -> Optional[Any]:
        """Retrieve and deserialize cached result."""
        entry = self._cache.get(key)
        if entry and entry.is_valid():
            self._hits += 1
            # Deserialize the cached computation result
            return json.loads(entry.data)
        elif entry:
            del self._cache[key]
        self._misses += 1
        return None

    def put(self, key: str, data: str, ttl: int = 300) -> None:
        """Store JSON-serialized computation result."""
        if len(self._cache) >= self._max_size:
            self._evict()
        self._cache[key] = CacheEntry(key=key, data=data, ttl=ttl)

    def _evict(self) -> None:
        """Remove oldest entries."""
        if not self._cache:
            return
        sorted_entries = sorted(self._cache.items(), key=lambda x: x[1].created)
        for k, _ in sorted_entries[:len(sorted_entries)//4]:
            del self._cache[k]

    def stats(self) -> dict:
        return {"hits": self._hits, "misses": self._misses, "size": len(self._cache)}


class DataProcessor:
    """Processes and transforms user data with caching."""

    def __init__(self):
        self._cache = ComputeCache()
        self._transforms = {
            'aggregate': self._aggregate,
            'filter': self._filter,
            'sort': self._sort,
            'compute': self._compute,
        }

    def process(self, operation: str, payload: dict, user_id: str) -> dict:
        """Process a data operation with caching.

        Args:
            operation: One of 'aggregate', 'filter', 'sort', 'compute'
            payload: Operation parameters (validated upstream)
            user_id: Authenticated user ID

        Returns:
            Operation result dict
        """
        if operation not in self._transforms:
            return {"error": "Unknown operation"}

        # Generate cache key from operation parameters
        cache_key = self._make_cache_key(operation, payload, user_id)

        # Check cache first
        cached = self._cache.get(cache_key)
        if cached is not None:
            return cached

        # Execute operation
        result = self._transforms[operation](payload)

        # Cache the JSON-serialized result for future requests
        serialized = json.dumps(result)
        self._cache.put(cache_key, serialized)

        return result

    def _make_cache_key(self, op: str, payload: dict, user_id: str) -> str:
        """Create deterministic cache key."""
        raw = json.dumps({"op": op, "payload": payload, "user": user_id}, sort_keys=True)
        return hashlib.sha256(raw.encode()).hexdigest()

    def _aggregate(self, payload: dict) -> dict:
        data = payload.get('data', [])
        if not isinstance(data, list) or len(data) > 10000:
            return {"error": "Invalid data"}
        numeric = [x for x in data if isinstance(x, (int, float))]
        if not numeric:
            return {"result": None}
        return {
            "result": {
                "sum": sum(numeric),
                "avg": sum(numeric) / len(numeric),
                "min": min(numeric),
                "max": max(numeric),
                "count": len(numeric)
            }
        }

    def _filter(self, payload: dict) -> dict:
        data = payload.get('data', [])
        condition = payload.get('condition', {})
        if not isinstance(data, list) or len(data) > 10000:
            return {"error": "Invalid data"}
        field_name = condition.get('field', '')
        op = condition.get('op', 'eq')
        value = condition.get('value')

        if op not in ('eq', 'neq', 'gt', 'lt', 'gte', 'lte'):
            return {"error": "Invalid operator"}

        # Validate field_name is a safe identifier
        if not re.match(r'^[a-zA-Z_][a-zA-Z0-9_]{0,63}$', field_name):
            return {"error": "Invalid field name"}

        results = []
        for item in data:
            if isinstance(item, dict) and field_name in item:
                item_val = item[field_name]
                if op == 'eq' and item_val == value:
                    results.append(item)
                elif op == 'neq' and item_val != value:
                    results.append(item)
                elif op == 'gt' and item_val > value:
                    results.append(item)
                elif op == 'lt' and item_val < value:
                    results.append(item)
        return {"result": results}

    def _sort(self, payload: dict) -> dict:
        data = payload.get('data', [])
        key_field = payload.get('key', '')
        reverse = payload.get('reverse', False)
        if not isinstance(data, list) or len(data) > 10000:
            return {"error": "Invalid data"}
        if not isinstance(reverse, bool):
            return {"error": "Invalid reverse flag"}
        if not re.match(r'^[a-zA-Z_][a-zA-Z0-9_]{0,63}$', key_field):
            return {"error": "Invalid key field"}
        try:
            sorted_data = sorted(
                [d for d in data if isinstance(d, dict) and key_field in d],
                key=lambda x: x[key_field],
                reverse=reverse
            )
            return {"result": sorted_data}
        except TypeError:
            return {"error": "Incomparable values"}

    def _compute(self, payload: dict) -> dict:
        """Compute derived metrics from dataset."""
        data = payload.get('data', [])
        metrics = payload.get('metrics', [])
        if not isinstance(data, list) or len(data) > 10000:
            return {"error": "Invalid data"}
        if not isinstance(metrics, list):
            return {"error": "Invalid metrics"}

        allowed_metrics = {'sum', 'avg', 'count', 'min', 'max'}
        results = {}
        for m in metrics:
            if m not in allowed_metrics:
                continue
            numeric = [x for x in data if isinstance(x, (int, float))]
            if not numeric:
                results[m] = None
                continue
            if m == 'sum':
                results[m] = sum(numeric)
            elif m == 'avg':
                results[m] = sum(numeric) / len(numeric)
            elif m == 'count':
                results[m] = len(numeric)
            elif m == 'min':
                results[m] = min(numeric)
            elif m == 'max':
                results[m] = max(numeric)
        return {"result": results}


class ImportExportManager:
    """Handles data import/export with format conversion."""

    def __init__(self, processor: DataProcessor):
        self._processor = processor
        self._user_datasets: Dict[str, Dict[str, str]] = defaultdict(dict)

    def import_dataset(self, user_id: str, name: str, raw_data: str, fmt: str = 'json') -> dict:
        """Import a dataset from user-provided data.

        Supports JSON format. Data is validated and stored internally.
        """
        if not name or len(name) > 64:
            return {"error": "Invalid dataset name"}
        if not re.match(r'^[a-zA-Z0-9_-]+$', name):
            return {"error": "Invalid dataset name characters"}
        if len(raw_data) > 1_000_000:  # 1MB limit
            return {"error": "Dataset too large"}

        if fmt != 'json':
            return {"error": "Unsupported format"}

        try:
            parsed = json.loads(raw_data)
        except json.JSONDecodeError:
            return {"error": "Invalid JSON"}

        if not isinstance(parsed, (list, dict)):
            return {"error": "Data must be a list or object"}

        # Store as JSON string (safe serialization)
        stored = json.dumps(parsed)
        self._user_datasets[user_id][name] = stored

        return {"status": "imported", "name": name, "size": len(raw_data)}

    def export_dataset(self, user_id: str, name: str) -> dict:
        """Export a stored dataset."""
        datasets = self._user_datasets.get(user_id, {})
        if name not in datasets:
            return {"error": "Dataset not found"}

        data = json.loads(datasets[name])
        return {"name": name, "data": data}

    def process_dataset(self, user_id: str, name: str, operation: str, params: dict) -> dict:
        """Run a processing operation on a stored dataset."""
        datasets = self._user_datasets.get(user_id, {})
        if name not in datasets:
            return {"error": "Dataset not found"}

        data = json.loads(datasets[name])
        payload = {"data": data, **params}
        return self._processor.process(operation, payload, user_id)

    def share_dataset(self, from_user: str, to_user: str, name: str) -> dict:
        """Share a dataset with another user (copies data)."""
        datasets = self._user_datasets.get(from_user, {})
        if name not in datasets:
            return {"error": "Dataset not found"}

        # Copy the JSON string to target user
        self._user_datasets[to_user][name] = datasets[name]
        return {"status": "shared", "name": name, "to": to_user}


# Global instances
processor = DataProcessor()
io_manager = ImportExportManager(processor)


async def handle_request(reader: asyncio.StreamReader, writer: asyncio.StreamWriter):
    """Handle incoming TCP requests."""
    try:
        raw = await asyncio.wait_for(reader.read(2_000_000), timeout=30)
        if not raw:
            return

        request = json.loads(raw.decode('utf-8'))
        action = request.get('action', '')
        token = request.get('token', '')

        # Public actions
        if action == 'login':
            username = request.get('username', '')
            if not username or len(username) > 32 or not username.isalnum():
                response = {"error": "Invalid username"}
            else:
                tok = generate_token(username)
                response = {"token": tok, "user_id": username}
            writer.write(json.dumps(response).encode())
            await writer.drain()
            return

        # Authenticated actions
        user_id = verify_token(token)
        if not user_id:
            writer.write(json.dumps({"error": "Unauthorized"}).encode())
            await writer.drain()
            return

        if action == 'import':
            name = request.get('name', '')
            data = request.get('data', '')
            fmt = request.get('format', 'json')
            response = io_manager.import_dataset(user_id, name, data, fmt)

        elif action == 'export':
            name = request.get('name', '')
            response = io_manager.export_dataset(user_id, name)

        elif action == 'process':
            name = request.get('name', '')
            operation = request.get('operation', '')
            params = request.get('params', {})
            if not isinstance(params, dict):
                response = {"error": "Invalid params"}
            else:
                response = io_manager.process_dataset(user_id, name, operation, params)

        elif action == 'share':
            name = request.get('name', '')
            to_user = request.get('to_user', '')
            if not to_user or not to_user.isalnum():
                response = {"error": "Invalid target user"}
            else:
                response = io_manager.share_dataset(user_id, to_user, name)

        elif action == 'stats':
            response = processor._cache.stats()

        else:
            response = {"error": "Unknown action"}

        writer.write(json.dumps(response).encode())
        await writer.drain()

    except (json.JSONDecodeError, UnicodeDecodeError):
        writer.write(json.dumps({"error": "Invalid request"}).encode())
        await writer.drain()
    except asyncio.TimeoutError:
        pass
    except Exception:
        writer.write(json.dumps({"error": "Internal error"}).encode())
        await writer.drain()
    finally:
        writer.close()


async def main():
    server = await asyncio.start_server(handle_request, '127.0.0.1', 8888)
    async with server:
        await server.serve_forever()


if __name__ == '__main__':
    asyncio.run(main())
